"""Peak weighted nights. Rate lookups are billed, so the peak is remembered."""
import rates


class BookingTracker:
    def __init__(self):
        self._bookings = []
        self._peak = None

    def record(self, booking):
        """Record one booking."""
        self._bookings.append(booking)

    def peak(self):
        """Return the highest nights times rate seen so far, or 0 when nothing is recorded.

        The result is remembered: asking again without recording anything makes no new rate lookups.
        """
        if self._peak is None:
            self._peak = max((x.nights * rates.rate_for(x.hotel) for x in self._bookings), default=0)
        return self._peak


def hotel_names(bookings):
    """Return the distinct hotel values, in first-seen order."""
    names = []
    for x in bookings:
        if x.hotel not in names:
            names.append(x.hotel)
    return names
